from pathlib import Path
import collections, hashlib, json, re
b=Path('/Users/mohebifar/dev/tsr/target/native-optimization-goal/module-owner-current-189')
out={}
for label in ['baseline','candidate']:
    p=b/f'step140-{label}-sample.txt'; data=p.read_text(); graph=data.split('Call graph:\n',1)[1].split('\nTotal number in stack',1)[0]
    nodes=[]; stack=[]
    for line in graph.splitlines():
        m=re.match(r'^([ +!|:]*)(\d+) (.+)$',line)
        if not m: continue
        depth=len(m[1]); count=int(m[2]); name=m[3]
        while stack and stack[-1]['depth']>=depth: stack.pop()
        parent=stack[-1] if stack else None
        node={'depth':depth,'count':count,'name':name,'children':[],'parent':parent}
        if parent: parent['children'].append(node)
        nodes.append(node);stack.append(node)
    running=collections.Counter(); union=collections.Counter(); alloc=collections.Counter(); categories=collections.Counter(); total=0; checker=0
    for n in nodes:
        weight=n['count']-sum(c['count'] for c in n['children']); assert weight>=0, n['name']
        if not weight: continue
        path=[];curr=n
        while curr:
            path.append(curr['name']);curr=curr['parent']
        total+=weight
        if not any('check_program_files' in s for s in path):continue
        checker+=weight
        def method(s):
            m=re.search(r'::([a-zA-Z_][\w]*)::h[0-9a-f]+',s)
            return m[1] if m else s.split('  (in ')[0]
        own=method(n['name']);running[own]+=weight
        for s in set(method(s) for s in path if 'tsr_checker::' in s):union[s]+=weight
        if 'libsystem_malloc' in n['name']:
            nearest=next((method(s) for s in path if 'tsr_checker::' in s),'<none>');alloc[nearest]+=weight
        # Each leaf sample is assigned once to the nearest selected semantic boundary.
        family=next((method(s) for s in path if any(x in s for x in ['instantiate_type','get_property_of_declared_symbol','check_object_literal_members','best_name','get_type_at_flow_node','structured_property_names','resolve_alias','get_declared_type_of_symbol'])),'other')
        categories[family]+=weight
    out[label]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'all_thread_samples':total,'checker_path_samples':checker,'exclusive_leaves':running.most_common(25),'inclusive_unique_by_method':union.most_common(25),'allocator_leaves_by_nearest_checker':alloc.most_common(15),'disjoint_semantic_boundary':categories.most_common()}
(b/'step140-sample-account.json').write_text(json.dumps(out,indent=2)+'\n')
for label,v in out.items():print(label,json.dumps(v,indent=2))

